select is(api.club_admin_command('b2000000-0000-4000-8000-000000000001','save_season','b8000000-0000-4000-8000-000000000006',0,'{"name":"Native season","starts_on":"2026-07-01","ends_on":"2027-06-30","winter_cutoff_at":"2026-12-31T23:00:00Z","target_minutes":0,"winter_target_minutes":0,"status":"active","reason":"native persisted organization proof"}','b9000000-0000-4000-8000-000000000007')->>'ok','true','native persisted command save_season');
