select is(api.club_admin_command('b2000000-0000-4000-8000-000000000001','save_task_type','b8000000-0000-4000-8000-000000000008',0,'{"category_id":"b8000000-0000-4000-8000-000000000007","name":"Native club task","active":true,"reason":"native persisted organization proof"}','b9000000-0000-4000-8000-000000000009')->>'ok','true','native persisted command save_task_type');
