select is(api.club_admin_command('b2000000-0000-4000-8000-000000000001','save_course_session','b8000000-0000-4000-8000-000000000011',0,'{"course_id":"b8000000-0000-4000-8000-000000000009","starts_at":"2026-10-01T09:00:00Z","ends_at":"2026-10-01T11:00:00Z","capacity":10,"qualification_type_id":"b8000000-0000-4000-8000-000000000010","qualification_valid_until":"2027-10-01T11:00:00Z","reason":"native persisted organization proof"}','b9000000-0000-4000-8000-000000000013')->>'ok','true','native persisted command save_course_session');
